                "average": 0.0,
                "min": 0.0,
                "max": 0.0,
                "total": 0.0
            }

        salaries = [emp['salary'] for emp in employees]
        return {
            "count": len(salaries),
            "average": sum(salaries) / len(salaries),
            "min": min(salaries),
            "max": max(salaries),
            "total": sum(salaries)
        }


